let Pc=/*#__NO_SIDE_EFFECTS__*/(a,b,c)=>{if(c<0)++c;if(c>1)--c;return c<1/6?a+(b-a)*6*c:c<.5?b:c<2/3?a+(b-a)*(2/3-c)*6:a},hslaToRgba=function(a){let e=a.hue/360,f=a.saturation/100,g=a.lightness/100,b=g,c=g,d=g;if(f!=0){let a=g<.5?g*(1+f):g+f-g*f,h=2*g-a;b=Pc(h,a,e+1/3);c=Pc(h,a,e);d=Pc(h,a,e-1/3)}return{red:Math.round(b*255),green:Math.round(c*255),blue:Math.round(d*255),alpha:a.alpha}};export{hslaToRgba};